-- T.K Group: additive schema plan (NOT APPLIED).
-- Generated by replica-architect, 2026-11-24. Read replica/architecture.md first.
--
-- Ground rules
--  * Purely additive. Nothing here alters, drops or renames an existing table,
--    column, function, policy or bucket. Existing RPCs (create_shipment,
--    set_status, confirm_payment, ...) keep working unchanged.
--  * Existing objects are referenced, never redefined. Their key types below
--    are INFERRED from the client code and must be checked against a schema
--    dump before this file is run (see "Step 0" in architecture.md):
--        profiles.id   uuid    (auth user id; high confidence)
--        shipments.id  text    (e.g. 'TK-...'; client upper-cases it; medium)
--        invoices.id   bigint  (client orders by id; medium)
--  * New money columns are integer cents + currency. Existing tables keep
--    their current price/amount columns; conversions happen in functions.
--  * Every new table has RLS on. Staff checks go through tk_has_role().
--  * Times are timestamptz (UTC). Display zone is decided in the client.

begin;

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

-- True if the caller's profile role is in the list. 'admin' always passes.
create or replace function public.tk_has_role(p_roles text[])
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid()
      and (p.role = 'admin' or p.role = any(p_roles))
  );
$$;

create or replace function public.tk_is_staff()
returns boolean language sql stable as $$
  select public.tk_has_role(array['herne_staff','support','accountant']);
$$;

create or replace function public.tk_touch_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;

-- ---------------------------------------------------------------------------
-- 1. Pricing: rates, weight breaks, surcharges, customer rules
--    Replaces the hard-coded RATE / MODES / BIZD constants in index.html.
--    Recon: S21, features "Rate sheets", "Surcharges", "Markup profiles".
-- ---------------------------------------------------------------------------

create table public.tk_rates (
  id uuid primary key default gen_random_uuid(),
  direction text not null check (direction in ('eu2sy','sy2eu')),
  goods_type text not null,                 -- matches TYPES keys: newc, used, elec, tools, mnew, mused, fam, oil, mn, ...
  mode text not null check (mode in ('road','sea','air')),
  unit text not null default 'kg' check (unit in ('kg','can','piece','cbm')),
  price_per_unit_cents integer not null check (price_per_unit_cents >= 0),
  min_charge_cents integer not null default 0 check (min_charge_cents >= 0),
  currency text not null default 'EUR' check (currency ~ '^[A-Z]{3}$'),
  transit_days_min smallint not null check (transit_days_min >= 0),
  transit_days_max smallint not null check (transit_days_max >= transit_days_min),
  valid_from date not null default current_date,
  valid_to date,
  active boolean not null default true,
  note text,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint tk_rates_valid_range check (valid_to is null or valid_to >= valid_from)
);
-- One active rate per lane key and start date; overlaps are prevented in tk_rate_upsert().
create unique index tk_rates_key on public.tk_rates (direction, goods_type, mode, unit, valid_from) where active;
create index tk_rates_lookup on public.tk_rates (direction, goods_type, mode) where active;

-- Weight breaks: "over 1000 kg pays 0.50 less" becomes a row, not code.
create table public.tk_rate_breaks (
  id uuid primary key default gen_random_uuid(),
  rate_id uuid not null references public.tk_rates(id) on delete cascade,
  min_qty numeric(12,3) not null check (min_qty > 0),
  price_per_unit_cents integer not null check (price_per_unit_cents >= 0),
  created_at timestamptz not null default now(),
  unique (rate_id, min_qty)
);
create index on public.tk_rate_breaks (rate_id);

create table public.tk_surcharges (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,               -- e.g. pickup, customs_export, insurance, fuel
  label_ar text not null, label_de text, label_en text,
  kind text not null check (kind in ('flat','per_unit','percent')),
  amount_cents integer,                    -- for flat / per_unit
  percent numeric(5,2),                    -- for percent
  applies_mode text check (applies_mode in ('road','sea','air')),   -- null = all
  applies_direction text check (applies_direction in ('eu2sy','sy2eu')),
  optional boolean not null default false, -- true = customer chooses it (add-on service)
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint tk_surcharge_amount check (
    (kind in ('flat','per_unit') and amount_cents is not null and percent is null) or
    (kind = 'percent' and percent is not null and amount_cents is null))
);

-- Customer-specific pricing: replaces the single 25% business discount.
create table public.tk_price_rules (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid references public.profiles(id) on delete cascade, -- null + role_scope = rule for a whole role
  role_scope text check (role_scope in ('customer','business')),
  goods_type text,                         -- null = all goods
  min_weight_kg numeric(12,3) not null default 0,
  discount_percent numeric(5,2) not null check (discount_percent between 0 and 100),
  valid_to date,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint tk_price_rule_target check (profile_id is not null or role_scope is not null)
);
create index on public.tk_price_rules (profile_id);
create index on public.tk_price_rules (role_scope) where profile_id is null;

-- ---------------------------------------------------------------------------
-- 2. Quotes: saved instant quotes and manual quotes for non-standard cargo
--    Recon: S02, S22, F01, F07.
-- ---------------------------------------------------------------------------

create table public.tk_quotes (
  id uuid primary key default gen_random_uuid(),
  ref text not null unique default ('Q-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),
  profile_id uuid references public.profiles(id) on delete set null, -- null = guest quote
  source text not null check (source in ('instant','manual')),
  direction text not null check (direction in ('eu2sy','sy2eu')),
  goods_type text not null,
  mode text not null check (mode in ('road','sea','air')),
  from_place text not null,
  to_place text not null,
  quantity numeric(12,3) not null check (quantity > 0),
  unit text not null default 'kg',
  breakdown jsonb not null default '[]',   -- [{code,label,amount_cents}]
  total_cents integer not null check (total_cents >= 0),
  currency text not null default 'EUR',
  transit_days_min smallint, transit_days_max smallint,
  status text not null default 'open' check (status in ('draft','open','accepted','expired','cancelled')),
  valid_until timestamptz not null default (now() + interval '7 days'),
  shipment_id text references public.shipments(id) on delete set null,  -- set when booked
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on public.tk_quotes (profile_id, created_at desc);
create index on public.tk_quotes (status, valid_until);
create index on public.tk_quotes (shipment_id);

-- ---------------------------------------------------------------------------
-- 3. Booking review and amendments (ops accepts / rejects / amends)
--    Recon: S19, F03, features "Ops review", "Booking amendments".
-- ---------------------------------------------------------------------------

create table public.tk_booking_reviews (
  shipment_id text primary key references public.shipments(id) on delete cascade,
  decision text not null default 'pending' check (decision in ('pending','accepted','rejected')),
  reason text,
  reviewed_by uuid references public.profiles(id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  constraint tk_review_reason check (decision <> 'rejected' or reason is not null)
);
create index on public.tk_booking_reviews (decision, created_at);

create table public.tk_amendments (
  id uuid primary key default gen_random_uuid(),
  shipment_id text not null references public.shipments(id) on delete cascade,
  requested_by uuid not null references public.profiles(id) on delete cascade,
  changes jsonb not null,                  -- {field: {from, to}}
  price_delta_cents integer not null default 0,
  status text not null default 'pending' check (status in ('pending','accepted','rejected','withdrawn')),
  decided_by uuid references public.profiles(id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create index on public.tk_amendments (shipment_id, created_at desc);
create index on public.tk_amendments (status) where status = 'pending';

-- ---------------------------------------------------------------------------
-- 4. Milestone estimates (estimated vs actual). Actuals stay in the
--    existing shipment_status_log; this only adds the "estimated" side.
--    Recon: S08, F05, feature "Estimated vs actual date per milestone".
-- ---------------------------------------------------------------------------

create table public.tk_milestone_estimates (
  shipment_id text not null references public.shipments(id) on delete cascade,
  step smallint not null check (step between 0 and 6),   -- index into the 7 existing statuses
  estimated_at timestamptz not null,
  reason text,                              -- e.g. 'customs hold', 'truck delayed'
  updated_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now(),
  primary key (shipment_id, step)
);

-- Exceptions: delay, customs hold, damage... shown as "urgent first" (S07).
create table public.tk_exceptions (
  id uuid primary key default gen_random_uuid(),
  shipment_id text not null references public.shipments(id) on delete cascade,
  kind text not null check (kind in ('delay','customs_hold','damage','missing_docs','payment_issue','other')),
  note text,
  visible_to_customer boolean not null default true,
  opened_by uuid references public.profiles(id) on delete set null,
  opened_at timestamptz not null default now(),
  resolved_at timestamptz
);
create index on public.tk_exceptions (shipment_id);
create index on public.tk_exceptions (opened_at desc) where resolved_at is null;

-- ---------------------------------------------------------------------------
-- 5. Invoices: status, due date, balance, PDF. 1-1 extension of the
--    existing invoices table (which keeps number, issued_at, amount).
--    Recon: S10, F08.
-- ---------------------------------------------------------------------------

create table public.tk_invoice_meta (
  invoice_id bigint primary key references public.invoices(id) on delete restrict,
  status text not null default 'open' check (status in ('open','paid','past_due','void')),
  due_date date,
  total_cents integer not null,
  paid_cents integer not null default 0 check (paid_cents >= 0),
  currency text not null default 'EUR',
  pdf_path text,                            -- storage: invoices/<profile_id>/<number>.pdf
  voided_at timestamptz, void_reason text,
  updated_at timestamptz not null default now(),
  constraint tk_invoice_void check ((status = 'void') = (voided_at is not null))
);
create index on public.tk_invoice_meta (status, due_date);

-- ---------------------------------------------------------------------------
-- 6. Card payments via Stripe Checkout (existing payments table keeps the
--    payment record; this tracks the provider session and webhook events).
-- ---------------------------------------------------------------------------

create table public.tk_checkout_sessions (
  id uuid primary key default gen_random_uuid(),
  provider text not null default 'stripe',
  provider_session_id text not null unique,
  profile_id uuid not null references public.profiles(id) on delete restrict,
  shipment_ids text[] not null,             -- a cart can pay several shipments
  amount_cents integer not null check (amount_cents > 0),
  currency text not null default 'EUR',
  status text not null default 'open' check (status in ('open','paid','expired','failed','refunded')),
  idempotency_key text not null unique,     -- from the client, stops double submits
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on public.tk_checkout_sessions (profile_id, created_at desc);

create table public.tk_webhook_events (
  provider text not null,
  event_id text not null,
  type text not null,
  payload jsonb not null,
  received_at timestamptz not null default now(),
  processed_at timestamptz,
  error text,
  primary key (provider, event_id)          -- webhooks arrive twice; second insert is a no-op
);

-- ---------------------------------------------------------------------------
-- 7. Notifications: per-event, per-channel preferences and an outbox for
--    email / WhatsApp / SMS / web push. In-app rows stay in the existing
--    notifications table. Recon: S12, F11.
-- ---------------------------------------------------------------------------

create table public.tk_notification_prefs (
  profile_id uuid not null references public.profiles(id) on delete cascade,
  event text not null check (event in (
    'booking_created','booking_accepted','booking_rejected','status_changed',
    'eta_changed','exception_opened','doc_rejected','invoice_issued',
    'payment_confirmed','chat_reply','delivered')),
  in_app boolean not null default true,
  email boolean not null default false,
  whatsapp boolean not null default false,
  sms boolean not null default false,
  push boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (profile_id, event)
);

create table public.tk_outbox (
  id uuid primary key default gen_random_uuid(),
  dedupe_key text not null unique,          -- e.g. 'status:TK-123:4:email'
  profile_id uuid references public.profiles(id) on delete cascade,
  channel text not null check (channel in ('email','whatsapp','sms','push')),
  template text not null,
  locale text not null default 'ar' check (locale in ('ar','de','en')),
  payload jsonb not null default '{}',
  status text not null default 'queued' check (status in ('queued','sending','sent','failed','skipped')),
  attempts smallint not null default 0,
  last_error text,
  send_after timestamptz not null default now(),
  sent_at timestamptz,
  created_at timestamptz not null default now()
);
create index on public.tk_outbox (status, send_after) where status in ('queued','failed');

create table public.tk_push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles(id) on delete cascade,
  endpoint text not null unique,
  p256dh text not null, auth text not null,
  user_agent text,
  created_at timestamptz not null default now()
);
create index on public.tk_push_subscriptions (profile_id);

-- ---------------------------------------------------------------------------
-- 8. Address book (today saved recipients live only in localStorage)
--    Recon: S13, feature "Saved addresses and parties".
-- ---------------------------------------------------------------------------

create table public.tk_address_book (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles(id) on delete cascade,
  kind text not null check (kind in ('sender','recipient','pickup')),
  name text not null,
  phone text,
  country text not null check (country in ('DE','NL','FR','SY')),
  city text,
  street text, postcode text,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on public.tk_address_book (profile_id, kind);
create unique index tk_address_default on public.tk_address_book (profile_id, kind) where is_default;

-- ---------------------------------------------------------------------------
-- 9. Company accounts with team members (business customers)
--    Recon: S14, feature "Company account with team members and roles".
-- ---------------------------------------------------------------------------

create table public.tk_orgs (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  vat_id text,
  billing_email text,
  created_by uuid not null references public.profiles(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.tk_org_members (
  org_id uuid not null references public.tk_orgs(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  role text not null default 'member' check (role in ('owner','member','viewer')),
  invited_by uuid references public.profiles(id) on delete set null,
  joined_at timestamptz not null default now(),
  primary key (org_id, profile_id)
);
create index on public.tk_org_members (profile_id);

create table public.tk_org_shipments (
  org_id uuid not null references public.tk_orgs(id) on delete cascade,
  shipment_id text not null references public.shipments(id) on delete cascade,
  primary key (org_id, shipment_id)
);
create index on public.tk_org_shipments (shipment_id);

-- ---------------------------------------------------------------------------
-- 10. Audit log for staff actions + rate limiting for public endpoints
-- ---------------------------------------------------------------------------

create table public.tk_audit_log (
  id bigint generated always as identity primary key,
  actor_id uuid references public.profiles(id) on delete set null,
  action text not null,                     -- 'rate.update', 'booking.accept', 'invoice.void', ...
  entity text not null, entity_id text not null,
  before jsonb, after jsonb,
  at timestamptz not null default now()
);
create index on public.tk_audit_log (entity, entity_id, at desc);
create index on public.tk_audit_log (actor_id, at desc);

create table public.tk_rate_limits (
  bucket text not null,                     -- e.g. 'track:<ip-hash>'
  window_start timestamptz not null,
  hits integer not null default 0,
  primary key (bucket, window_start)
);

-- ---------------------------------------------------------------------------
-- updated_at triggers
-- ---------------------------------------------------------------------------
create trigger t_upd before update on public.tk_rates            for each row execute function public.tk_touch_updated_at();
create trigger t_upd before update on public.tk_surcharges       for each row execute function public.tk_touch_updated_at();
create trigger t_upd before update on public.tk_quotes           for each row execute function public.tk_touch_updated_at();
create trigger t_upd before update on public.tk_invoice_meta     for each row execute function public.tk_touch_updated_at();
create trigger t_upd before update on public.tk_checkout_sessions for each row execute function public.tk_touch_updated_at();
create trigger t_upd before update on public.tk_notification_prefs for each row execute function public.tk_touch_updated_at();
create trigger t_upd before update on public.tk_address_book     for each row execute function public.tk_touch_updated_at();
create trigger t_upd before update on public.tk_orgs             for each row execute function public.tk_touch_updated_at();

-- ---------------------------------------------------------------------------
-- Row level security
-- Writes to pricing, reviews, estimates, invoices, outbox and audit go
-- through security-definer RPCs only (no direct insert/update policies).
-- ---------------------------------------------------------------------------
alter table public.tk_rates               enable row level security;
alter table public.tk_rate_breaks         enable row level security;
alter table public.tk_surcharges          enable row level security;
alter table public.tk_price_rules         enable row level security;
alter table public.tk_quotes              enable row level security;
alter table public.tk_booking_reviews     enable row level security;
alter table public.tk_amendments          enable row level security;
alter table public.tk_milestone_estimates enable row level security;
alter table public.tk_exceptions          enable row level security;
alter table public.tk_invoice_meta        enable row level security;
alter table public.tk_checkout_sessions   enable row level security;
alter table public.tk_webhook_events      enable row level security;
alter table public.tk_notification_prefs  enable row level security;
alter table public.tk_outbox              enable row level security;
alter table public.tk_push_subscriptions  enable row level security;
alter table public.tk_address_book        enable row level security;
alter table public.tk_orgs                enable row level security;
alter table public.tk_org_members         enable row level security;
alter table public.tk_org_shipments       enable row level security;
alter table public.tk_audit_log           enable row level security;
alter table public.tk_rate_limits         enable row level security;

-- Public price list: anyone (incl. guests) may read active rates and surcharges.
create policy read_active on public.tk_rates       for select using (active or public.tk_is_staff());
create policy read_all    on public.tk_rate_breaks for select using (true);
create policy read_active on public.tk_surcharges  for select using (active or public.tk_is_staff());
-- Price rules are private: own rules or staff.
create policy read_own on public.tk_price_rules for select
  using (profile_id = auth.uid() or public.tk_is_staff());

-- Owner-or-staff read for per-shipment data. Ownership is shipments.owner (seen in client).
create policy read_own on public.tk_quotes for select
  using (profile_id = auth.uid() or public.tk_is_staff());
create policy read_own on public.tk_booking_reviews for select
  using (public.tk_is_staff() or exists (select 1 from public.shipments s where s.id = shipment_id and s.owner = auth.uid()));
create policy read_own on public.tk_amendments for select
  using (requested_by = auth.uid() or public.tk_is_staff());
create policy read_own on public.tk_milestone_estimates for select
  using (public.tk_is_staff() or exists (select 1 from public.shipments s where s.id = shipment_id and s.owner = auth.uid()));
create policy read_own on public.tk_exceptions for select
  using (public.tk_is_staff() or (visible_to_customer and exists (select 1 from public.shipments s where s.id = shipment_id and s.owner = auth.uid())));
create policy read_own on public.tk_invoice_meta for select
  using (public.tk_has_role(array['accountant']) or exists (
    select 1 from public.invoices i join public.shipments s on s.id = i.shipment_id
    where i.id = invoice_id and s.owner = auth.uid()));
create policy read_own on public.tk_checkout_sessions for select
  using (profile_id = auth.uid() or public.tk_has_role(array['accountant']));

-- Self-service tables: the user manages their own rows directly.
create policy own_all on public.tk_notification_prefs for all
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());
create policy own_all on public.tk_push_subscriptions for all
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());
create policy own_all on public.tk_address_book for all
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());

-- Orgs: members read; owners manage members through RPCs.
create policy member_read on public.tk_orgs for select
  using (public.tk_is_staff() or exists (select 1 from public.tk_org_members m where m.org_id = id and m.profile_id = auth.uid()));
create policy member_read on public.tk_org_members for select
  using (public.tk_is_staff() or exists (select 1 from public.tk_org_members m where m.org_id = tk_org_members.org_id and m.profile_id = auth.uid()));
create policy member_read on public.tk_org_shipments for select
  using (public.tk_is_staff() or exists (select 1 from public.tk_org_members m where m.org_id = tk_org_shipments.org_id and m.profile_id = auth.uid()));

-- Staff-only reads.
create policy admin_read on public.tk_audit_log for select using (public.tk_has_role(array[]::text[]));  -- admin only
create policy staff_read on public.tk_outbox    for select using (public.tk_is_staff());
-- tk_webhook_events, tk_rate_limits: no policies = service role only.

-- ---------------------------------------------------------------------------
-- Core functions (signatures + the important bodies). The rest are listed
-- in architecture.md > API and follow the same pattern:
--   security definer, set search_path = public, role check first,
--   write audit row, enqueue notifications.
-- ---------------------------------------------------------------------------

-- Server-side price: the single source of truth used by quotes and bookings.
create or replace function public.tk_price(
  p_direction text, p_goods text, p_mode text, p_qty numeric,
  p_addons text[] default '{}', p_profile uuid default auth.uid())
returns table (total_cents integer, breakdown jsonb, transit_days_min smallint, transit_days_max smallint, rate_id uuid)
language plpgsql stable security definer set search_path = public as $$
declare
  r public.tk_rates;
  unit_cents integer;
  base integer;
  disc numeric := 0;
  lines jsonb := '[]';
  s record;
  extra integer;
begin
  if p_qty is null or p_qty <= 0 then raise exception 'invalid quantity'; end if;

  select * into r from public.tk_rates
   where active and direction = p_direction and goods_type = p_goods and mode = p_mode
     and valid_from <= current_date and (valid_to is null or valid_to >= current_date)
   order by valid_from desc limit 1;
  if not found then raise exception 'lane not served' using errcode = 'P0002'; end if;

  select coalesce((select b.price_per_unit_cents from public.tk_rate_breaks b
                    where b.rate_id = r.id and b.min_qty <= p_qty
                    order by b.min_qty desc limit 1), r.price_per_unit_cents)
    into unit_cents;

  base := greatest(r.min_charge_cents, round(unit_cents * p_qty)::integer);
  lines := lines || jsonb_build_object('code','freight','amount_cents',base);

  -- best matching customer rule: personal beats role-wide
  select pr.discount_percent into disc from public.tk_price_rules pr
   left join public.profiles p on p.id = p_profile
   where (pr.profile_id = p_profile or (pr.profile_id is null and pr.role_scope = p.role))
     and (pr.goods_type is null or pr.goods_type = p_goods)
     and pr.min_weight_kg <= p_qty
     and (pr.valid_to is null or pr.valid_to >= current_date)
   order by (pr.profile_id is not null) desc, pr.discount_percent desc limit 1;
  if coalesce(disc,0) > 0 then
    lines := lines || jsonb_build_object('code','discount','amount_cents', -round(base * disc / 100)::integer);
    base := base - round(base * disc / 100)::integer;
  end if;

  for s in select * from public.tk_surcharges
            where active
              and (applies_mode is null or applies_mode = p_mode)
              and (applies_direction is null or applies_direction = p_direction)
              and (not optional or code = any(p_addons)) loop
    extra := case s.kind when 'flat' then s.amount_cents
                         when 'per_unit' then round(s.amount_cents * p_qty)::integer
                         else round(base * s.percent / 100)::integer end;
    lines := lines || jsonb_build_object('code', s.code, 'amount_cents', extra);
    base := base + extra;
  end loop;

  return query select base, lines, r.transit_days_min, r.transit_days_max, r.id;
end $$;

-- Guests and customers get an instant quote; stored so a booking can reference it.
create or replace function public.tk_quote_create(
  p_direction text, p_goods text, p_mode text, p_from text, p_to text,
  p_qty numeric, p_addons text[] default '{}')
returns public.tk_quotes
language plpgsql security definer set search_path = public as $$
declare q public.tk_quotes; pr record;
begin
  select * into pr from public.tk_price(p_direction, p_goods, p_mode, p_qty, p_addons, auth.uid());
  insert into public.tk_quotes (profile_id, source, direction, goods_type, mode, from_place, to_place,
                                quantity, breakdown, total_cents, transit_days_min, transit_days_max)
  values (auth.uid(), 'instant', p_direction, p_goods, p_mode, p_from, p_to,
          p_qty, pr.breakdown, pr.total_cents, pr.transit_days_min, pr.transit_days_max)
  returning * into q;
  return q;
end $$;

-- Public tracking: needs ref + PIN (the PIN the customer already gets at booking).
-- Returns only milestone data, never names, phones or addresses. Rate-limited.
create or replace function public.tk_track_public(p_ref text, p_pin text, p_client_hash text)
returns table (step smallint, at timestamptz, estimated_at timestamptz)
language plpgsql security definer set search_path = public as $$
declare w timestamptz := date_trunc('minute', now()); n integer;
begin
  insert into public.tk_rate_limits as l (bucket, window_start, hits)
  values ('track:' || p_client_hash, w, 1)
  on conflict (bucket, window_start) do update set hits = l.hits + 1
  returning hits into n;
  if n > 10 then raise exception 'too many requests' using errcode = 'P0001'; end if;

  -- ASSUMPTION: shipments.pin stores the PIN (client reads s.pin). If it is
  -- hashed, compare with crypt() instead. Verify in Step 0.
  if not exists (select 1 from public.shipments s where s.id = upper(p_ref) and s.pin = p_pin) then
    raise exception 'not found' using errcode = 'P0002';
  end if;

  return query
    select gs.step::smallint, l.at, e.estimated_at
      from generate_series(0, 6) gs(step)
      left join lateral (select max(x.at) as at from public.shipment_status_log x
                          where x.shipment_id = upper(p_ref) and x.status = gs.step) l on true
      left join public.tk_milestone_estimates e on e.shipment_id = upper(p_ref) and e.step = gs.step
     order by gs.step;
end $$;

-- Staff: accept or reject a new booking.
create or replace function public.tk_review_booking(p_ship text, p_accept boolean, p_reason text default null)
returns void language plpgsql security definer set search_path = public as $$
declare changed integer;
begin
  if not public.tk_has_role(array['herne_staff','support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  insert into public.tk_booking_reviews (shipment_id, decision, reason, reviewed_by, reviewed_at)
  values (p_ship, case when p_accept then 'accepted' else 'rejected' end, p_reason, auth.uid(), now())
  on conflict (shipment_id) do update
    set decision = excluded.decision, reason = excluded.reason,
        reviewed_by = excluded.reviewed_by, reviewed_at = excluded.reviewed_at
    where public.tk_booking_reviews.decision = 'pending';   -- first decision wins
  get diagnostics changed = row_count;
  if changed = 0 then raise exception 'already reviewed' using errcode = 'P0001'; end if;  -- no second audit/notification
  insert into public.tk_audit_log (actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'booking.review', 'shipment', p_ship, jsonb_build_object('accept', p_accept, 'reason', p_reason));
  perform public.tk_notify(p_ship, case when p_accept then 'booking_accepted' else 'booking_rejected' end,
                           jsonb_build_object('reason', p_reason));
end $$;

-- Fan out one event to the owner's chosen channels. In-app goes to the
-- existing notifications table; the rest go to the outbox (dedupe_key makes
-- a repeated call harmless).
create or replace function public.tk_notify(p_ship text, p_event text, p_payload jsonb default '{}')
returns void language plpgsql security definer set search_path = public as $$
declare owner_id uuid; pref public.tk_notification_prefs; ch text; loc text;
begin
  select s.owner into owner_id from public.shipments s where s.id = p_ship;
  if owner_id is null then return; end if;
  select * into pref from public.tk_notification_prefs where profile_id = owner_id and event = p_event;
  -- defaults when the user never saved prefs: in-app + whatsapp (matches today's client defaults)
  if not found then pref.in_app := true; pref.whatsapp := true; pref.email := false; pref.sms := false; pref.push := false; end if;
  loc := 'ar';  -- TODO Step 0: read profiles.locale if it exists; else keep 'ar'

  -- ASSUMPTION: notifications(user_id, kind, payload). Verify in Step 0.
  if pref.in_app then
    insert into public.notifications (user_id, kind, payload)
    values (owner_id, p_event, p_payload || jsonb_build_object('shipment_id', p_ship));
  end if;

  foreach ch in array array['email','whatsapp','sms','push'] loop
    if (ch = 'email' and pref.email) or (ch = 'whatsapp' and pref.whatsapp)
       or (ch = 'sms' and pref.sms) or (ch = 'push' and pref.push) then
      insert into public.tk_outbox (dedupe_key, profile_id, channel, template, locale, payload)
      values (p_event || ':' || p_ship || ':' || coalesce(p_payload->>'step','') || ':' || ch,
              owner_id, ch, p_event, loc, p_payload || jsonb_build_object('shipment_id', p_ship))
      on conflict (dedupe_key) do nothing;
    end if;
  end loop;
end $$;

-- Lock down function execution: helpers are internal.
revoke all on function public.tk_notify(text, text, jsonb) from public, anon, authenticated;
revoke all on function public.tk_price(text, text, text, numeric, text[], uuid) from anon;  -- guests use tk_quote_create
grant execute on function public.tk_quote_create(text, text, text, text, text, numeric, text[]) to anon, authenticated;
-- Only the 'track' Edge Function (service role) calls this: it computes the IP hash
-- server-side, so a client cannot dodge the rate limit by sending a fresh hash.
revoke all on function public.tk_track_public(text, text, text) from public, anon, authenticated;
grant execute on function public.tk_track_public(text, text, text) to service_role;
grant execute on function public.tk_review_booking(text, boolean, text) to authenticated;

